mapper.sql:
where t.shop_code = #{query.shopCode}

  and t.transactioncode like concat('%', #{query.transactionCode}, '%')


  and t.accountcode = #{query.accountCode}


  and t.transtype = #{query.transType}


  and t.categorycode = #{query.categoryCode}


  and t.biztype = #{query.bizType}


  and t.bizcode like concat('%', #{query.bizCode}, '%')


  and t.partyname like concat('%', #{query.partyName}, '%')


  and t.status = #{query.status}


  and t.createtime >= #{query.createTimeBegin}


  and t.createtime <= #{query.createTimeEnd}


  and t.tradetime >= #{query.tradeTimeBegin}


  and t.tradetime <= #{query.tradeTimeEnd}

mapper.select:
select tt.*, cu.nick_name as create_user_name, au.nick_name as audit_user_name, pu.nick_name as complete_user_name from (
( select , '${suffix}' as table_suffix from sdsorder.u_f_transaction_${suffix} t
order by coalesce(t.tradetime, t.createtime) desc, t.id desc limit #{cap} )
) tt left join sys_user cu on cu.user_name = tt.create_user left join sys_user au on au.user_name = tt.audit_user left join sys_user pu on pu.user_name = tt.complete_user order by coalesce(tt.trade_time, tt.create_time) desc, tt.table_suffix desc, tt.id desc limit #{offset}, #{limit}

select coalesce(sum(c), 0)
  from (

    select count(1) as c
      from sdsorder.u_f_transaction_${suffix} t


  ) x

select ,
       '${tableSuffix}' as table_suffix
  from sdsorder.u_f_transaction_${tableSuffix} t
 where t.shop_code = #{shopCode}
   and t.transactioncode = #{transactionCode}
 for update

mapper.delete:
delete from sdsorder.u_f_transaction_${tableSuffix}
 where shop_code = #{shopCode}
   and transactioncode = #{transactionCode}
   and status in ('草稿', '已驳回')

mapper.select:
select count(1) from sdsorder.u_f_transaction_${tableSuffix}
 where shop_code = #{shopCode}
   and accountcode = #{accountCode}

select count(1) from sdsorder.u_f_transaction_${tableSuffix}
 where shop_code = #{shopCode}
   and categorycode = #{categoryCode}

select coalesce(sum(abs(amount)), 0)
  from sdsorder.u_f_transaction_${tableSuffix}
 where shop_code = #{shopCode}
   and biztype = #{bizType}
   and bizcode = #{bizCode}
   and status = '已完成'

select bizcode as bizcode,
       max(coalesce(tradetime, completetime, createtime)) as lasttime
  from sdsorder.u_f_transaction_${tableSuffix}
 where shop_code = #{shopCode}
   and biztype = #{bizType}
   and transtype = #{transType}
   and status = '已完成'
   and bizcode is not null
 group by bizcode


where t.shop_code = #{shopCode}
  and t.biztype = #{bizType}
  and t.bizcode = #{bizCode}
order by coalesce(t.tradetime, t.createtime) desc, t.id desc


where t.shop_code = #{shopCode}
  and t.biztype = '销售'
  and t.transtype = '收入'
  and t.status = '待审核'
  and t.currency = #{currency}
order by coalesce(t.tradetime, t.createtime) desc, t.id desc

mapper.update:
update sdsorder.u_f_transaction_${tableSuffix}
   set status = #{t.status},
       bizcode = null,
       bizsummary = #{t.bizSummary},
       completeuser = null,
       rejectreason = #{t.rejectReason},
       audituser = coalesce(#{t.auditUser}, audituser),
       audittime = coalesce(#{t.auditTime}, audittime)
 where shop_code = #{t.shopCode}
   and transactioncode = #{t.transactionCode}
   and status = #{expectedStatus}
